async function getUserPreferences() {
  try {
    const res = await fetch('https://api.example.com/user/preferences', {
      cache: 'no-store',
    })
    if (!res.ok) {
      throw new Error(`Failed to fetch preferences: ${res.status}`)
    }
    return res.json() as Promise<Record<string, unknown>>
  } catch {
    // Return mock data for build time / when the API is unavailable
    return {
      theme: 'system',
      notificationsEnabled: true,
      language: 'en',
    }
  }
}

function formatPreferenceValue(value: unknown): string {
  if (value === null || value === undefined) {
    return '—'
  }
  if (typeof value === 'object') {
    return JSON.stringify(value)
  }
  return String(value)
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences()

  return (
    <div>
      <h2>User Dashboard</h2>
      <dl>
        {Object.entries(preferences).map(([key, value]) => (
          <div key={key}>
            <dt>{key}</dt>
            <dd>{formatPreferenceValue(value)}</dd>
          </div>
        ))}
      </dl>
    </div>
  )
}

